import{_ as o,C as t,o as n,c as d,j as l,a as h,G as i,a7 as s}from"./chunks/framework.BvFspj3b.js";const f=JSON.parse('{"title":"使用说明","description":"ICC-CE 的三种工作模式、界面布局、工具栏功能介绍以及日常使用场景","frontmatter":{"title":"使用说明","description":"ICC-CE 的三种工作模式、界面布局、工具栏功能介绍以及日常使用场景"},"headers":[],"relativePath":"cn/guide/instruction-manual.md","filePath":"cn/guide/instruction-manual.md"}'),c={name:"cn/guide/instruction-manual.md"};function u(b,a,m,p,q,P){const e=t("ArticleMetadata"),r=t("KnownBugs");return n(),d("div",null,[a[0]||(a[0]=l("h1",{id:"使用说明",tabindex:"-1"},[h("使用说明 "),l("a",{class:"header-anchor",href:"#使用说明","aria-label":'Permalink to "使用说明"'},"​")],-1)),i(e),i(r),a[1]||(a[1]=s('<h2 id="三种工作模式" tabindex="-1">三种工作模式 <a class="header-anchor" href="#三种工作模式" aria-label="Permalink to &quot;三种工作模式&quot;">​</a></h2><p>ICC-CE 提供三种核心工作模式，可通过工具栏上的模式按钮切换：</p><h3 id="屏幕批注模式-默认" tabindex="-1">屏幕批注模式（默认） <a class="header-anchor" href="#屏幕批注模式-默认" aria-label="Permalink to &quot;屏幕批注模式（默认）&quot;">​</a></h3><p>在屏幕上方覆盖一层透明画布，可在任何软件界面上方书写标注。</p><ul><li>适合在 PPT、PDF、浏览器、视频播放器等上方实时标注</li><li>工具栏浮动在屏幕边缘，方便快速切换工具</li><li>支持墨迹保存、截图、撤销/重做等操作</li></ul><h3 id="白板模式" tabindex="-1">白板模式 <a class="header-anchor" href="#白板模式" aria-label="Permalink to &quot;白板模式&quot;">​</a></h3><p>全屏纯色背景，充当电子白板使用。</p><ul><li>全屏书写空间，适合课堂板书</li><li>支持插入图片、背景网格</li><li>工具栏位于屏幕两侧，提供更多书写工具</li><li>支持扩展画布，可无限延伸书写空间</li></ul><h3 id="鼠标模式" tabindex="-1">鼠标模式 <a class="header-anchor" href="#鼠标模式" aria-label="Permalink to &quot;鼠标模式&quot;">​</a></h3><p>关闭墨迹绘制，鼠标穿透到下层应用正常操作。</p><ul><li>可与屏幕批注模式快速切换</li><li>适合在书写和操作应用之间频繁切换的场景</li></ul><h2 id="界面与工具栏" tabindex="-1">界面与工具栏 <a class="header-anchor" href="#界面与工具栏" aria-label="Permalink to &quot;界面与工具栏&quot;">​</a></h2><h3 id="工具栏布局" tabindex="-1">工具栏布局 <a class="header-anchor" href="#工具栏布局" aria-label="Permalink to &quot;工具栏布局&quot;">​</a></h3><p>工具栏默认浮动在屏幕右侧边缘，主要包含：</p><table tabindex="0"><thead><tr><th>区域</th><th>功能</th></tr></thead><tbody><tr><td>画笔工具</td><td>笔、荧光笔、激光笔、橡皮擦</td></tr><tr><td>颜色选择</td><td>快速调色盘、自定义颜色</td></tr><tr><td>宽度调节</td><td>笔触粗细滑块</td></tr><tr><td>模式切换</td><td>屏幕批注 / 白板 / 鼠标模式</td></tr><tr><td>工具箱</td><td>设置、截图、清屏、保存、撤销/重做</td></tr><tr><td>PPT 控制</td><td>翻页、跳转（放映时自动出现）</td></tr></tbody></table><h3 id="工具栏状态" tabindex="-1">工具栏状态 <a class="header-anchor" href="#工具栏状态" aria-label="Permalink to &quot;工具栏状态&quot;">​</a></h3><ul><li><strong>展开状态</strong>：完整显示所有工具按钮</li><li><strong>收纳状态</strong>：缩为屏幕边缘细条，鼠标悬停或点击展开</li><li><strong>迷你栏</strong>：闲置一段时间后自动缩为紧凑圆角迷你工具栏（需在设置中开启）</li></ul><h3 id="快捷面板" tabindex="-1">快捷面板 <a class="header-anchor" href="#快捷面板" aria-label="Permalink to &quot;快捷面板&quot;">​</a></h3><p>收纳模式下，屏幕底部会显示快捷面板，提供常用工具的快速访问。</p><h2 id="日常使用场景" tabindex="-1">日常使用场景 <a class="header-anchor" href="#日常使用场景" aria-label="Permalink to &quot;日常使用场景&quot;">​</a></h2><h3 id="课堂授课" tabindex="-1">课堂授课 <a class="header-anchor" href="#课堂授课" aria-label="Permalink to &quot;课堂授课&quot;">​</a></h3><ol><li>打开 PPT 开始放映，ICC-CE 自动进入标注模式</li><li>使用笔在幻灯片上书写重点</li><li>使用荧光笔高亮关键内容</li><li>翻页时墨迹自动保存，翻回自动恢复</li><li>课后可导出带有标注的截图或时间胶囊</li></ol><h3 id="在线教学" tabindex="-1">在线教学 <a class="header-anchor" href="#在线教学" aria-label="Permalink to &quot;在线教学&quot;">​</a></h3><ol><li>使用屏幕批注模式在课件或浏览器上实时标注</li><li>结合白板模式进行板书讲解</li><li>使用激光笔引导注意力</li><li>截图保存讲课内容发给学生</li></ol><h3 id="会议演示" tabindex="-1">会议演示 <a class="header-anchor" href="#会议演示" aria-label="Permalink to &quot;会议演示&quot;">​</a></h3><ol><li>在演示文档上方实时标注</li><li>使用形状识别快速绘制标准图形</li><li>使用双指缩放/平移查看细节</li><li>会后保存墨迹文件和截图归档</li></ol><h3 id="日常办公" tabindex="-1">日常办公 <a class="header-anchor" href="#日常办公" aria-label="Permalink to &quot;日常办公&quot;">​</a></h3><ol><li>截图标注：截取屏幕内容后添加标注</li><li>文档批注：在 PDF 或文档上书写批注</li><li>草稿本：快速记录想法和示意图</li></ol>',28))])}const x=o(c,[["render",u]]);export{f as __pageData,x as default};
